    for row in cases.split(separator: "\n") {
        let parts = row.split(separator: "=")
        try #require(parts.count == 2)
        let expected = try #require(UInt64(parts[1], radix: 16))
        var sum = GlifiGraphBinary64Sum()
        var reverse = GlifiGraphBinary64Sum()
        let values = try parts[0].split(separator: ",").map { token in
            Double(bitPattern: try #require(UInt64(token, radix: 16)))
        }
        for value in values { sum = try sum.adding(value) }
        for value in values.reversed() { reverse = try reverse.adding(value) }
        #expect(sum.rounded.bitPattern == expected)
        #expect(sum == reverse)
    }
}
